import{_ as s,C as n,c as r,o,a3 as t,G as i}from"./chunks/framework.Dokpd4od.js";const q=JSON.parse('{"title":"Maintenance requests","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/maintenance/requests/index.md","filePath":"master/supply-chain/maintenance/requests/index.md","lastUpdated":1793074831000}'),l={name:"master/supply-chain/maintenance/requests/index.md"};function c(h,e,p,u,d,m){const a=n("ImagePopup");return o(),r("div",null,[e[0]||(e[0]=t('<h1 id="maintenance-requests" tabindex="-1">Maintenance requests <a class="header-anchor" href="#maintenance-requests" aria-label="Permalink to &quot;Maintenance requests&quot;">​</a></h1><p>A maintenance request is a job card for one piece of equipment. It says what needs attention, who does it, and when. You use requests to report problems, plan regular check-ups, and keep a record of every repair.</p><blockquote><p><strong>In simple words:</strong> A request is a to-do item for a machine. It moves from <strong>New Request</strong> to <strong>Repaired</strong> (or <strong>Scrap</strong>) as people work on it.</p></blockquote><p>Open <code>Maintenance → Maintenance Requests</code>.</p><h2 id="corrective-and-preventive-requests" tabindex="-1">Corrective and preventive requests <a class="header-anchor" href="#corrective-and-preventive-requests" aria-label="Permalink to &quot;Corrective and preventive requests&quot;">​</a></h2><p>Every request has a <strong>Maintenance Type</strong>. The type tells you why the work exists.</p><ul><li><strong>Corrective:</strong> Something is already wrong and needs a fix. Example: the <strong>Hydraulic Press 200T</strong> leaks oil, so you raise <strong>Hydraulic press oil leak</strong>.</li><li><strong>Preventive:</strong> Nothing is broken. You plan the work to stop a failure later. Example: <strong>Monthly lubrication, Hydraulic Press 200T</strong>, repeated every month.</li></ul><p>A preventive request can repeat on its own. See <a href="./preventive-maintenance.html">Preventive maintenance</a>.</p><h2 id="the-life-of-a-request" tabindex="-1">The life of a request <a class="header-anchor" href="#the-life-of-a-request" aria-label="Permalink to &quot;The life of a request&quot;">​</a></h2>',9)),i(a,{src:"/images1/maintenance/req_lifecycle_stage_bar.png",alt:"Stage bar of the Hydraulic press oil leak request showing New Request, In Progress, Repaired and Scrap"}),e[1]||(e[1]=t(`<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>New Request  →  In Progress  →  Repaired</span></span>
<span class="line"><span>                            ↘  Scrap</span></span></code></pre></div><ol><li>Someone reports the problem. The request starts in <strong>New Request</strong>.</li><li>A technician takes the job. Choose <strong>In Progress</strong> on the <strong>Edit</strong> page and click <strong>Save changes</strong>.</li><li>The work ends in <strong>Repaired</strong> or <strong>Scrap</strong>. These two stages carry the <strong>Done</strong> flag, so they close the request.</li></ol><p>You can add or rename stages. See <a href="./../setup/stages.html">Stages</a>.</p><h2 id="who-does-what" tabindex="-1">Who does what <a class="header-anchor" href="#who-does-what" aria-label="Permalink to &quot;Who does what&quot;">​</a></h2><ul><li><strong>The reporter</strong> creates the request and picks the equipment.</li><li><strong>The responsible person</strong> (the technician) does the work and moves the request along.</li><li><strong>The team</strong> groups technicians. See <a href="./../setup/maintenance-teams.html">Maintenance teams</a>.</li></ul><h2 id="in-this-section" tabindex="-1">In this section <a class="header-anchor" href="#in-this-section" aria-label="Permalink to &quot;In this section&quot;">​</a></h2><ul><li><a href="./create-request.html">Create a maintenance request</a>: fill the form and save.</li><li><a href="./process-request.html">Process a request</a>: move stages, add notes and activities, delete or restore.</li><li><a href="./preventive-maintenance.html">Preventive maintenance</a>: repeat a job every few days, weeks, months or years.</li><li><a href="./request-list.html">Maintenance request list</a>: tabs, search, group by and bulk actions.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Before you start, set up a <a href="./../setup/maintenance-teams.html">team</a>, the <a href="./../setup/stages.html">stages</a> and your <a href="./../equipment/add-equipment.html">equipment</a>.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../calendar/maintenance-calendar.html">Maintenance calendar</a></li><li><a href="./../equipment/">Equipment</a></li></ul>`,10))])}const f=s(l,[["render",c]]);export{q as __pageData,f as default};
